import{z as n,x as i,o as B,c as d,q as r,j as o,D as A,d as a,s as t,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"评测在环","description":"","frontmatter":{"title":"评测在环","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-eval-in-loop.md","filePath":"llm/rlsys-eval-in-loop.md","lastUpdated":1791063341000}'),p={name:"llm/rlsys-eval-in-loop.md"};function m(C,E,F,h,D,f){const l=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="评测在环" tabindex="-1">评测在环 <a class="header-anchor" href="#评测在环" aria-label="Permalink to &quot;评测在环&quot;">​</a></h1><div class="epigraph"><p>训练奖励告诉你模型在优化什么，评测告诉你它变成了什么——把后者搬进环里，代价是要为它分配卡与纪律。</p><footer>—— 据 Cobbe 等 2021 的 held-out 纪律与对齐评测实践整理</footer></div><p><a href="/llm/rlsys-hacking-monitor">上一课</a>的交叉对照要靠独立金标活着；金标从哪来、多久量一次、由谁守门，是本课的内容：评测在环。训练循环里周期性跑一套受控评测，用它的曲线做选点、停训与回归门。它与<a href="/llm/aeval-map">对齐评测收束</a>的差别在视角：那边讲怎么测得准，这边讲怎么让测量以固定节奏喂进训练决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>评测在环有三个系统问题。预算：评测与训练抢同一批卡，测得越勤越贵，训练吞吐被摊薄；测得太稀，回归发现得太晚。卫生：评测提示一旦混进训练分布，曲线只报喜——污染在 RL 里尤其隐蔽，因为训练提示本就有相当部分来自内部题库与自采。稳定性：RL 训练用高温采样，评测要用确定解码，解码参数、模板、停止条件的任何漂移都会伪装成能力变化。三个问题共享一个答案：评测要被当成有版本、有预算、有 owner 的生产资产来运营。</p><p><span class="marginnote">直觉类比：评测在环像体检中心的定期抽血——训练是日常锻炼，快速层是每次锻炼后的心率（勤、便宜、粗），重层是季度全套化验（贵、准、定结论）。只看心率会漏病，只做化验追不上节奏，所以三层都要有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层评测栈。快速层：固定几百到几千条可验证题，贪心解码，答案匹配，每若干步一次，分钟级，管回归检测。重层：跨域混合题加 LLM 裁判或人审，低频（每天或每几百步），管金标对照与检查点选点。专项层：安全与对齐套件（<a href="/llm/aeval-map">对齐评测收束</a>、<a href="/llm/aeval-alignment-tax">对齐税的测量</a>），里程碑触发，管「为了分数牺牲了什么」。工程纪律四条。题库单向闸门：提示进入评测集后从训练采样池摘除，操作留痕。解码配置与模型配置一起版本化：曲线只许同配置比较。检查点按评测选而不用训练奖励选：训练奖励高只说明代理被优化。回归门自动化：重层分数掉过阈值自动停训或回滚，把「要不要停」从会上挪进代码。</p><p><span class="marginnote">为什么重要：题库闸门漏一条，优化器就会把它当捷径反复刷——评测分数虚高、回归检测失灵，而且污染不可逆（题一进训练分布就再也「测不准」了）。这是整套评测公信力里最不能省的一道闸。</span></p><p><span class="marginnote">评测用贪心（或固定种子的低温采样），训练探索用高温采样：同一检查点的两条曲线天然不可比。把配置哈希印在监控曲线旁边，是防止把温度改动误读成能力变化的最便宜手段。</span></p>',10)),(B(),o(s,null,{default:A(()=>[t(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%E6%AD%A5%EF%BC%88%E9%87%87%E6%A0%B7%E8%A7%A3%E7%A0%81%EF%BC%89%22%5D%20--%3E%7C%22%E6%AF%8F%E8%8B%A5%E5%B9%B2%E6%AD%A5%22%7C%20EV1%5B%22%E5%BF%AB%E9%80%9F%E5%B1%82%EF%BC%9A%E5%8F%AF%E9%AA%8C%E8%AF%81%E9%A2%98%20%2B%20%E8%B4%AA%E5%BF%83%22%5D%0A%20%20EV1%20--%3E%7C%22%E5%BC%82%E5%B8%B8%22%7C%20G1%5B%22%E5%9B%9E%E5%BD%92%E5%91%8A%E8%AD%A6%22%5D%0A%20%20TR%20--%3E%7C%22%E4%BD%8E%E9%A2%91%22%7C%20EV2%5B%22%E9%87%8D%E5%B1%82%EF%BC%9A%E8%A3%81%E5%88%A4%2F%E4%BA%BA%E5%AE%A1%20%2B%20%E9%87%91%E6%A0%87%E5%AF%B9%E7%85%A7%22%5D%0A%20%20EV2%20--%3E%20G2%5B%22%E9%80%89%E7%82%B9%2F%E5%81%9C%E8%AE%AD%E5%9B%9E%E5%BD%92%E9%97%A8%EF%BC%88%E8%87%AA%E5%8A%A8%E5%8C%96%EF%BC%89%22%5D%0A%20%20TR%20--%3E%7C%22%E9%87%8C%E7%A8%8B%E7%A2%91%22%7C%20EV3%5B%22%E4%B8%93%E9%A1%B9%E5%B1%82%EF%BC%9A%E5%AE%89%E5%85%A8%E4%B8%8E%E5%AF%B9%E9%BD%90%E5%A5%97%E4%BB%B6%22%5D%0A%20%20EV3%20--%3E%20REP%5B%22%E8%83%BD%E5%8A%9B%E5%AF%B9%E5%AF%B9%E9%BD%90%E7%A8%8E%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("评测在环能当守门人，靠三层信号的正交：快速层敏感（题多、勤、便宜，抓回归），重层权威（金标与人审，定真相），专项层兜底（安全与对齐税，防单点优化）。频率与成本的机制账：设训练步墙钟为 \\(T\\)，快速层成本占比控制在个位数百分点，其灵敏度足以把「连续两档掉分」当回归信号；重层低频但每次都是决策事件（选点、停训），必须可复现——裁判模型版本、提示模板、解码参数全部冻结。这把评测集变成生产资产：它有版本、有变更日志、有 owner，与训练数据管理同级；"),e("a",{href:"/llm/rm-benchmarks"},"RM 评测基准与排行榜"),a("讨论的公信力问题，在内部评测上同样成立——评测的权威来自它不被训练环接触。")],-1)),(B(),o(s,null,{default:A(()=>[t(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%89%E5%B1%82%E8%AF%84%E6%B5%8B%E9%9D%A0%E4%BB%80%E4%B9%88%E5%88%86%E5%B7%A5%EF%BC%9F%22%5D%20--%3E%20F%5B%22%E5%BF%AB%E9%80%9F%E5%B1%82%EF%BC%9A%E6%95%8F%E6%84%9F%22%5D%0A%20%20Q%20--%3E%20H%5B%22%E9%87%8D%E5%B1%82%EF%BC%9A%E6%9D%83%E5%A8%81%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E4%B8%93%E9%A1%B9%E5%B1%82%EF%BC%9A%E5%85%9C%E5%BA%95%22%5D%0A%20%20F%20--%3E%20F1%5B%22%E9%A2%98%E5%A4%9A%E5%8B%A4%E4%BE%BF%E5%AE%9C%EF%BC%9A%E6%8A%93%E5%9B%9E%E5%BD%92%22%5D%0A%20%20H%20--%3E%20H1%5B%22%E9%87%91%E6%A0%87%E4%BA%BA%E5%AE%A1%EF%BC%9A%E5%AE%9A%E7%9C%9F%E7%9B%B8%E3%80%81%E9%80%89%E7%82%B9%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E5%AE%89%E5%85%A8%E4%B8%8E%E5%AF%B9%E9%BD%90%E7%A8%8E%EF%BC%9A%E9%98%B2%E5%8D%95%E7%82%B9%E4%BC%98%E5%8C%96%22%5D%0A%20%20F1%20--%3E%20G%5B%22%E5%90%88%E6%88%90%E5%AE%88%E9%97%A8%EF%BC%9A%E9%98%88%E5%80%BC%E8%87%AA%E5%8A%A8%E5%81%9C%E8%AE%AD%E6%88%96%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20H1%20--%3E%20G%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">数字实例：每几十步就在同一套题上选一次检查点，一万步下来等于做了几百次「选择」，选中高分的那个点带着可观的运气成分——这就是终评要换新题的原因：选点用的题已经被你的选择过程 Goodhart 过了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>在环评测不替代最终离线评测：选点过拟合的风险随评测次数上升——在同一套题上选了几十个检查点后，「评测分数」本身也在被 Goodhart，终评要换新题与 held-out 人审。快速层的题会随时间泄漏（写进论文、撞上公开题库），要定期轮换。评测与训练共享集群时，评测负载的抖动会反噬训练节奏，需要配额与优先级，这也是预算纪律的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层栈：快速可验证层管回归、重层管金标与选点、专项层管安全与对齐税；频率与权威性成反比。</li><li>题库单向闸门：进评测即出训练池，日志留痕；题库定期轮换防泄漏。</li><li>解码配置与模型配置同版本化，曲线只许同配置比较；检查点按评测选，不按训练奖励选。</li><li>回归门自动化：阈值触发停训或回滚；终评换新题与 held-out 人审防选点过拟合。</li><li>出处：Cobbe 等 2021（GSM8K 的 held-out 纪律）；据对齐评测与内部金标实践整理。</li></ul>',5))])}const _=n(p,[["render",m]]);export{c as __pageData,_ as default};
